\label{basisAAs}
Let $\mathfrak{Ma}\textrm{-}\mathrm{As}\<X\>$ be the free $\mathfrak{Ma}$-associative algebra, generated by the set $X=\big\{x_i \big\}_{i \in I}.$ 
Then the following set of elements 
\begin{center}
    ${\mathfrak B}=\big\{  \ x_i,\  x_{i}x_{j},\  x_{i} (x_{j}x_{k})  \ \big\}_{i, j, k \in I}$
\end{center}
gives a basis of $\mathfrak{Ma}$-$\mathrm{As}\<X\>.$

\label{basisAAs}
Let $\mathfrak{Ma}\textrm{-}S\mathrm{As}\<X\>$ be the free $\mathfrak{Ma}$-shift associative algebra, generated by the set $X=\big\{x_i \big\}_{i \in I}.$ 
Then the following set of elements 
\begin{center}
    ${\mathfrak B}=\big\{  \ x_i,\  x_{i}x_{j},\  x_{i} (x_{j}x_{k}), \  (x_{i} x_{j})(x_{m} x_{k})   \ \big\}_{i, j, k, m \in I; \  j<m}$
\end{center}
gives a basis of $\mathfrak{Ma}\textrm{-}S\mathrm{As}\<X\>.$

An algebra $\mathfrak{Ma}$-${\rm Leib\<X\>}$ satisfies the following identities:
\begin{equation}\label{ALeib1}
a\big(bc+cb\big) \ =\ 0,
\end{equation}
\begin{equation}\label{ALeib2}
a\big(b(cd)\big)\ =\ 0,
\end{equation}
\begin{equation}\label{ALeib3}
a\big((bc)d\big) \ =\ 0.
\end{equation}

The algebra $\mathfrak{Ma}\text{-}$${\rm Nov}\<X\>$ satisfies the following identities:
\begin{align}
(ad)(bc)&=a\big((bd)c\big)=b\big((ad)c\big), \label{ANovId1}\\
\big(a(cd)\big)b&=a\big(c(db)\big), \label{ANovId2}\\
(db)\big((ce)a\big)&=c\big(((de)b)a\big), \label{ANovId3}\\
c\big(((de)b)a\big)&=d\big(((cb)e)a\big), \label{ANovId4}
\end{align}

Let $\mathrm{Var}$ be a quadratic operad. Then
\[
\mathrm{Var}=\mathfrak{Ma}\text{-}\mathrm{Var}
\]
if and only if the defining identities of $\mathrm{Var}$ can be chosen in the form
\begin{equation}\label{MaVar-left}
\sum_{\sigma \in \mathbb{S}_3} \alpha_\sigma \bigl(x_{\sigma(1)}x_{\sigma(2)}\bigr)x_{\sigma(3)}=0
\end{equation}
and
\begin{equation}\label{MaVar-right}
\sum_{\sigma \in \mathbb{S}_3} \beta_\sigma \,x_{\sigma(1)}\bigl(x_{\sigma(2)}x_{\sigma(3)}\bigr)=0.
\end{equation}

It is easy to see, that there are $\beta,\gamma \in  \mathbb{C},$ such that 
${\rm A}$ satisfies the following identity 
\begin{center}
    $(xy)z+\beta (yz)x +\gamma (zx)y=0.$\end{center}
Which is equivalent to identities 
\begin{center}    
$(yz)x+\beta (zx)y +\gamma (xy)z=0$ and 
$(zx)y+\beta (xy)z +\gamma (yz)x=0.$  
\end{center}
Summarizing the last $3$ identities, we have 
$(1+\beta+\gamma) \big((xy)z+   (yz)x +   (zx)y\big)=0.$  Then,
\begin{enumerate}
    \item[I.] If $\beta+\gamma \neq-1,$ then ${\rm A}$ is a Jacobi-Jordan algebra.

    \item[II.] If $\gamma=-\beta-1,$ then ${\rm A}$  satisfies the following pair of identities
    \begin{center}
$(xy)z+\beta (yz)x-(1+\beta)(xz)y=0$ and 
$(xz)y+\beta (zy)x -(1+\beta)(xy)z=0;$\\
$(xy)z+\beta (yz)x -(1+\beta)(xz)y=0$ and 
$(yx)z+\beta (xz)y -(1+\beta)(yz)x=0.$
    \end{center}
\noindent Subsequently, subtracting these identities, we have 
\begin{center}
    $(2+\beta)\big((xy)z-(xz)y\big)=0$\  and \  
    $(2\beta+1)\big((xy)z-(xz)y\big)=0.$
\end{center}
\noindent     It means that  ${\rm A}$ is associative.



\end{enumerate}

It is easy to see, that there are $\beta,\gamma \in  \mathbb{C},$ such that 
${\rm A}$ satisfies the following identity 
\begin{center}
    $(xy)z+\beta (yz)x +\gamma (zx)y=0.$\end{center}
Which is equivalent to identities 
\begin{center}    
$(yz)x+\beta (zx)y +\gamma (xy)z=0$ and 
$(zx)y+\beta (xy)z +\gamma (yz)x=0.$  
\end{center}
Summarizing the last $3$ identities, we have 
$(1+\beta+\gamma) \big((xy)z+   (yz)x +   (zx)y\big)=0.$  Then,
\begin{enumerate}
    \item[I.] If $\beta+\gamma \neq-1,$ then ${\rm A}$ is a Lie algebra.

    \item[II.] If $\gamma=-\beta-1,$ then ${\rm A}$  satisfies the following  identities
    \begin{center}
$(xy)z+\beta (yz)x+(1+\beta)(xz)y=0,$ 

$(xz)y+\beta (zy)x +(1+\beta)(xy)z=0,$

$(yx)z+\beta (xz)y +(1+\beta)(yz)x=0.$
    \end{center}
\noindent  Summing the first identity with the second and third, we have
\begin{center}
    $(2+\beta)\big((xy)z+(xz)y\big)=0$\  and \  
    $(2\beta+1)\big((xz)y+(yz)x\big)=0.$
\end{center}
\noindent     It means that  ${\rm A}$ is anti-associative.
\end{enumerate}

If a variety of algebras is defined by the  family $\Omega$ of $n$ polynomial identities
\begin{center}
    $\Omega= \Big\{\sum\limits_{\sigma \in \mathbb{S}_3}
    \big(\alpha_\sigma^j (x_{\sigma(1)}x_{\sigma(2)})x_{\sigma(3)}+
    \beta_\sigma^j x_{\sigma(1)}(x_{\sigma(2)}x_{\sigma(3)}) \big) \ = \ 0 \Big\}_{1\leq j\leq n},$
\end{center}
then the variety of Manin anti-$\Omega$-algebras is defined by the following family of identities 

\begin{center}
    $\Omega^{\mathfrak a}= \Big\{\sum\limits_{\sigma \in \mathbb{S}_3}  (-1)^{\sigma}\big(\alpha_\sigma^j (x_{\sigma(1)}x_{\sigma(2)})x_{\sigma(3)}-
     \beta_\sigma^j x_{\sigma(1)}(x_{\sigma(2)}x_{\sigma(3)}) \big)\ = \ 0  \Big\}_{1\leq j\leq n}.$
\end{center}
